"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["33940"],{95587(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.integrantes_invalidos","status":422,"titulo":"A banca deve ter ao menos um integrante"},"descricao":{"codigo":"uniplus.selecao.banca.integrantes_invalidos","requisitos":["UNI-REQ-0275","UNI-REQ-0276"],"oQueAconteceu":["A regra de delibera\xe7\xe3o da banca declara menos de 1 integrante. A banca tem ao\\nmenos uma pessoa titular: ela pode ter uma s\xf3 (UNI-REQ-0276), mas n\xe3o pode ter\\nnenhuma, porque ningu\xe9m poderia deliberar ou praticar o ato.","A recusa vem na lista `errors[]` da resposta, no caminho do campo recusado, por exemplo `fases[0].bancasRequeridas[0].regraDeDeliberacao.integrantes` na banca da fase e `etapas[0].bancas[0].regraDeDeliberacao.integrantes` na banca da etapa."],"comoResolver":["Informe no campo `integrantes` um n\xfamero inteiro a partir de 1, o que o edital\\ndeclara para a banca. Depois de corrigido o n\xfamero, o qu\xf3rum e o m\xednimo de\\nintegrantes s\xe3o conferidos em fun\xe7\xe3o dele, e t\xeam recusa pr\xf3pria:\\n[qu\xf3rum fora do intervalo](/erros/uniplus.selecao.banca.quorum_fora_do_intervalo) e\\n[integrantes abaixo do m\xednimo](/erros/uniplus.selecao.banca.integrantes_abaixo_do_minimo)."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);